    """Vectorized GM -> GM copy with a grid-stride loop.

    The whole tile is loaded into registers as one aligned vector and stored
    back, which reaches HBM bandwidth without the extra UB staging round-trip
    of ``tle.dsa.copy`` (and is measurably cheaper for small tiles).
    ``n_elements`` stays int32: the grid-stride loop keeps every offset inside
    the 32-bit range even for the largest benchmarked tensors.
    """
    pid = tl.program_id(axis=0)
    step = tl.num_programs(axis=0) * BLOCK_SIZE
    lanes = tl.arange(0, BLOCK_SIZE)
    base = pid * BLOCK_SIZE
    while base < n_elements:
        offsets = base + lanes
        mask = offsets < n_elements
        tl.store(y_ptr + offsets, tl.load(x_ptr + offsets, mask=mask), mask=mask)
        base += step


